        /// <summary>Formats a row for diagnostics.</summary>
        public static string Format(int row)
        {
            return "row " + row + " mask=0x" + RowM[row].ToString("X4")
                 + " val=0x" + RowW[row].ToString("X2") + " len=" + RowN[row]
                 + " " + Mnem[RowS[row]] + " [" + Syn[RowSyn[row]] + "] ops=" + RowC[row];
        }
    }
